    private void tune(LiveTvData.Channel next){if(closed)return;channel=next;getContext().getSharedPreferences("lite_tv",0).edit().putString("selected",next.identity).putString("selected_alias",next.alias).apply();ready=false;failed=false;blocked=false;quality="";programmes=Collections.emptyMap();main.removeCallbacks(timeout);main.removeCallbacks(hideInfo);main.removeCallbacks(hideBadge);message.setText(t("Tuning…","Sintonizando…"));message.setVisibility(VISIBLE);badge.setText(t("LIVE","DIRECTO"));badge.setVisibility(VISIBLE);showInfo();load();try{television.setStreamVolume(1f);television.tune(channel.inputId,TvContract.buildChannelUri(channel.providerId));main.postDelayed(timeout,25000);}catch(RuntimeException unavailable){failure(t("Playback is unavailable on this television.","La reproducción no está disponible en esta televisión."));}}
    private void intro(){badge.setVisibility(VISIBLE);showInfo();main.removeCallbacks(hideBadge);main.postDelayed(hideBadge,4000);main.postDelayed(hideInfo,6000);}
    private void showInfo(){infoShown=true;info.setVisibility(pickerShown?GONE:VISIBLE);main.removeCallbacks(hideInfo);if(ready&&!failed&&!blocked)main.postDelayed(hideInfo,6000);}
    private void failure(String reason){main.removeCallbacks(timeout);ready=false;failed=true;showInfo();badge.setVisibility(GONE);message.setText(reason+"\n"+t("OK · Retry     Hold OK · Open television     Back · Guide","OK · Reintentar     Mantener OK · Abrir televisión     Atrás · Guía"));message.setVisibility(VISIBLE);}
    private void load(){if(closed)return;generation++;if(cancellation!=null)cancellation.cancel();if(job!=null)job.cancel(true);cancellation=new CancellationSignal();CancellationSignal signal=cancellation;int token=generation;List<LiveTvData.Channel> page=new ArrayList<>();page.add(channel);if(pickerShown)for(int i=pickerPage*6;i<Math.min(pickerValues.size(),pickerPage*6+6);i++)if(!page.contains(pickerValues.get(i)))page.add(pickerValues.get(i));long now=System.currentTimeMillis()/1000;job=worker.submit(()->{Map<String,List<LiveTvData.Programme>> values;try{values=nowNext(source.programmes(page,now,now+24*3600,signal),page,now);}catch(Exception unavailable){values=Collections.emptyMap();}Map<String,List<LiveTvData.Programme>> first=values;main.post(()->{if(!closed&&token==generation){programmes=first;updateInfo(Collections.emptyMap());if(pickerShown)drawPicker(Collections.emptyMap());}});Map<String,Bitmap> artwork=new HashMap<>();for(LiveTvData.Channel c:page){if(signal.isCanceled()||Thread.currentThread().isInterrupted())return;Bitmap b=logos.read(c);if(b!=null)artwork.put(c.id,b);}Map<String,List<LiveTvData.Programme>> result=values;main.post(()->{if(closed||token!=generation)return;programmes=result;updateInfo(artwork);if(pickerShown)drawPicker(artwork);});try{if(source.refreshGuide(channels,signal))main.post(()->{if(!closed&&token==generation){logos.clear();load();}});}catch(Exception offline){/* Native or cached EPG stays usable. */}});updateInfo(Collections.emptyMap());}
    private void updateInfo(Map<String,Bitmap> artwork){long now=System.currentTimeMillis()/1000;LiveTvData.Programme p=current(programmes,channel,now),next=next(programmes,channel,now);boolean upcoming=nextProgramme.bind(next==null?null:next.title,next==null?0:next.start,next==null?0:next.end,now);int width=upcoming?894:1436;for(View v:new View[]{title,subtitle,remaining,progress}){FrameLayout.LayoutParams layout=(FrameLayout.LayoutParams)v.getLayoutParams();if(layout.width!=width){layout.width=width;v.setLayoutParams(layout);}}title.setText(p==null?channel.name:p.title);subtitle.setText((favourites.has(channel,channels)?"★ ":"")+channel.name+(p==null?"":" · "+time(p.start)+"–"+time(p.end)));remaining.setText(p==null?t("No programme information","Sin programación"):LiveTvActivity.remainingText(p.remainingMinutes(now)));progress.value(p==null?0:p.progress(now));for(Iterator<Logo> it=logoViews.iterator();it.hasNext();){Logo logo=it.next();if(logo.getParent()==info){info.removeView(logo);logo.clear();it.remove();}}Logo logo=new Logo(getContext(),channel);logo.bitmap(artwork.get(channel.id));put(info,logo,80,128,120,120);logoViews.add(logo);}
    private void openPicker(){pickerShown=true;pickerValues=pickerValues();pickerPage=Math.max(0,pickerValues.indexOf(channel))/6;picker.setVisibility(VISIBLE);info.setVisibility(GONE);main.removeCallbacks(hideInfo);drawPicker(Collections.emptyMap());load();}
    private void closePicker(){selectPress.cancel();pickerShown=false;picker.setVisibility(GONE);clearPicker();showInfo();requestFocus();}
    private void clearPicker(){pickerSignature="";for(Iterator<Logo> it=logoViews.iterator();it.hasNext();){Logo logo=it.next();if(logo.getParent()!=info){logo.clear();it.remove();}}pickerRows.clear();picker.removeAllViews();}
    private void drawPicker(Map<String,Bitmap> artwork){String signature=pickerPage+":"+pickerFavorites;for(int i=pickerPage*6;i<Math.min(pickerValues.size(),pickerPage*6+6);i++){LiveTvData.Channel item=pickerValues.get(i);signature+=":"+item.id+":"+favourites.has(item,channels)+":"+item.id.equals(channel.id);}if(signature.equals(pickerSignature)&&picker.getChildCount()>0){updatePickerRows(artwork);return;}String focused="",tab="";int oldRow=0;View before=picker.findFocus();if(!pickerFocusRows&&before!=null&&before.getTag() instanceof String&&((String)before.getTag()).startsWith("@"))tab=(String)before.getTag();for(int i=0;i<pickerRows.size();i++)if(pickerRows.get(i).hasFocus()){focused=(String)pickerRows.get(i).getTag();oldRow=i;}clearPicker();pickerSignature=signature;Context c=getContext();put(picker,text(c,t("Channels","Canales"),30,VelaTheme.WHITE),32,26,610,48);TextView listTab=button(c,(pickerFavorites?"":"✓ ")+t("List","Lista"),()->filterPicker(false)),favTab=button(c,(pickerFavorites?"✓ ":"")+"★ "+t("Favourites","Favoritos"),()->filterPicker(true));listTab.setTag("@list");favTab.setTag("@favorites");put(picker,listTab,32,86,286,50);put(picker,favTab,330,86,310,50);put(picker,text(c,t("OK · Watch    Hold OK ★    Back · Close","OK · Ver    Mantener OK ★    Atrás · Cerrar"),17,VelaTheme.MUTED),32,950,622,34);View target=null;long now=System.currentTimeMillis()/1000;
        for(int i=pickerPage*6;i<Math.min(pickerValues.size(),pickerPage*6+6);i++){LiveTvData.Channel item=pickerValues.get(i);int row=i-pickerPage*6;FrameLayout card=new FrameLayout(c);card.setFocusable(true);card.setFocusableInTouchMode(true);card.setDefaultFocusHighlightEnabled(false);card.setTag(item.id);card.setBackground(plate(item.id.equals(channel.id)?VelaTheme.RAISED:VelaTheme.CARD,20));Logo logo=new Logo(c,item);logo.bitmap(artwork.get(item.id));put(card,logo,14,22,72,72);logoViews.add(logo);TextView name=text(c,(item.id.equals(channel.id)?"▶ ":"")+(favourites.has(item,channels)?"★ ":"")+item.name,22,VelaTheme.WHITE);name.setTag("name");put(card,name,112,10,474,34);LiveTvData.Programme p=current(programmes,item,now);TextView show=text(c,p==null?t("No programme information","Sin programación"):p.title,19,VelaTheme.SECONDARY);show.setTag("show");put(card,show,112,49,474,29);TextView left=text(c,p==null?"":LiveTvActivity.remainingText(p.remainingMinutes(now)),17,VelaTheme.SECONDARY);left.setTag("left");put(card,left,112,85,474,27);Progress bar=new Progress(c);bar.setTag("progress");bar.value(p==null?0:p.progress(now));put(card,bar,112,112,474,4);put(picker,card,24,160+row*128,648,120);pickerRows.add(card);card.setOnFocusChangeListener((v,f)->card.setBackground(plate(f?0xFF484A57:item.id.equals(channel.id)?VelaTheme.RAISED:VelaTheme.CARD,20)));card.setOnClickListener(v->{closePicker();if(!item.id.equals(channel.id))tune(item);});card.setOnLongClickListener(v->{toggleFavorite(item);return true;});TvRemotePress press=new TvRemotePress(card,card::performClick,card::performLongClick);card.setOnKeyListener((v,k,e)->{if(press.key(e))return true;if(e.getAction()!=0)return false;if(k==KeyEvent.KEYCODE_DPAD_UP&&row==0&&pickerPage>0){pickerPage--;drawPicker(Collections.emptyMap());pickerRows.get(pickerRows.size()-1).requestFocus();load();return true;}if(k==KeyEvent.KEYCODE_DPAD_DOWN&&row==5&&(pickerPage+1)*6<pickerValues.size()){pickerPage++;drawPicker(Collections.emptyMap());pickerRows.get(0).requestFocus();load();return true;}if(k==KeyEvent.KEYCODE_DPAD_LEFT){closePicker();return true;}return false;});if(item.id.equals(focused)||focused.isEmpty()&&item.id.equals(channel.id))target=card;}
        TextView count=text(c,pickerValues.isEmpty()?t("No favourites yet","Aún no tienes favoritos"):(pickerPage*6+1)+"–"+Math.min(pickerValues.size(),pickerPage*6+6)+" / "+pickerValues.size(),17,VelaTheme.MUTED);put(picker,count,32,1000,610,26);if(target==null&&!pickerRows.isEmpty())target=pickerRows.get(Math.min(oldRow,pickerRows.size()-1));if(tab.equals("@list"))listTab.requestFocus();else if(tab.equals("@favorites"))favTab.requestFocus();else if(target!=null)target.requestFocus();else favTab.requestFocus();}
    private void updatePickerRows(Map<String,Bitmap> artwork){long now=System.currentTimeMillis()/1000;for(int i=0;i<pickerRows.size();i++){View row=pickerRows.get(i);LiveTvData.Channel item=pickerValues.get(pickerPage*6+i);LiveTvData.Programme p=current(programmes,item,now);((TextView)row.findViewWithTag("show")).setText(p==null?t("No programme information","Sin programación"):p.title);((TextView)row.findViewWithTag("left")).setText(p==null?"":LiveTvActivity.remainingText(p.remainingMinutes(now)));((Progress)row.findViewWithTag("progress")).value(p==null?0:p.progress(now));if(artwork.containsKey(item.id))((Logo)((FrameLayout)row).getChildAt(0)).bitmap(artwork.get(item.id));}}
    private List<LiveTvData.Channel> pickerValues(){if(!pickerFavorites)return channels;List<LiveTvData.Channel> list=new ArrayList<>();for(LiveTvData.Channel c:channels)if(favourites.has(c,channels))list.add(c);return list;}
    private void filterPicker(boolean value){if(pickerFavorites==value)return;pickerFavorites=value;pickerValues=pickerValues();pickerPage=Math.max(0,pickerValues.indexOf(channel))/6;pickerFocusRows=true;drawPicker(Collections.emptyMap());pickerFocusRows=false;load();}
    private void toggleFavorite(LiveTvData.Channel item){favourites.toggle(item,channels);Toast.makeText(getContext(),favourites.has(item,channels)?t("Added to favourites","Añadido a favoritos"):t("Removed from favourites","Quitado de favoritos"),Toast.LENGTH_SHORT).show();if(pickerShown){pickerValues=pickerValues();pickerPage=Math.min(pickerPage,Math.max(0,(pickerValues.size()-1)/6));drawPicker(Collections.emptyMap());}load();}
    private void selectClick(){if(blocked)host.nativeTv(channel);else if(failed)tune(channel);else if(infoShown){infoShown=false;main.removeCallbacks(hideInfo);info.setVisibility(GONE);}else showInfo();}
    boolean remote(KeyEvent e){int key=e.getKeyCode();if(pickerShown){if(key==KeyEvent.KEYCODE_BACK&&e.getAction()==KeyEvent.ACTION_UP){closePicker();return true;}return key==KeyEvent.KEYCODE_BACK;}
        if(selectPress.key(e))return true;
        if(key==KeyEvent.KEYCODE_BACK){if(e.getAction()==KeyEvent.ACTION_UP)host.exit();return true;}
        if(e.getAction()==KeyEvent.ACTION_DOWN){if(key==KeyEvent.KEYCODE_DPAD_RIGHT){openPicker();return true;}if(key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN){openPicker();int index=pickerValues.indexOf(channel)+(key==KeyEvent.KEYCODE_DPAD_UP?-1:1);if(index>=0&&index<pickerValues.size()){pickerPage=index/6;drawPicker(Collections.emptyMap());for(View row:pickerRows)if(pickerValues.get(index).id.equals(row.getTag()))row.requestFocus();load();}return true;}if(key==KeyEvent.KEYCODE_CHANNEL_UP||key==KeyEvent.KEYCODE_CHANNEL_DOWN){if(e.getRepeatCount()==0){int direction=key==KeyEvent.KEYCODE_CHANNEL_UP?1:-1,index=channels.indexOf(channel),next=(index+direction+channels.size())%channels.size();tune(channels.get(next));}return true;}if(key==KeyEvent.KEYCODE_DPAD_LEFT){showInfo();return true;}}return key==KeyEvent.KEYCODE_DPAD_RIGHT||key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN||key==KeyEvent.KEYCODE_CHANNEL_UP||key==KeyEvent.KEYCODE_CHANNEL_DOWN;
    }
    public void close(){selectPress.cancel();if(closed)return;closed=true;generation++;main.removeCallbacksAndMessages(null);if(cancellation!=null)cancellation.cancel();if(job!=null)job.cancel(true);worker.shutdownNow();television.setCallback(null);television.reset();for(Logo v:logoViews)v.clear();logoViews.clear();logos.close();programmes=Collections.emptyMap();channels.clear();removeAllViews();}
    private float pixelScale=1;
    private android.graphics.drawable.GradientDrawable plate(int color,int radius){return LiteTvUi.plate(color,Math.round(radius*pixelScale));}
    /** Pixel-sized controls avoid a transformed overlay being clipped beside the native TvView in 4K. */
    private final class CanvasStage extends FrameLayout {
        private final WeakHashMap<View,Geometry> geometry=new WeakHashMap<>();
        CanvasStage(Context c){super(c);}
        protected void onMeasure(int w,int h){int width=MeasureSpec.getSize(w),height=MeasureSpec.getSize(h);if(width<=0||height<=0){setMeasuredDimension(width,height);return;}float scale=Math.min(width/1920f,height/1080f),ratio=scale/pixelScale;pixelScale=scale;resize(overlay,ratio);setMeasuredDimension(width,height);overlay.measure(MeasureSpec.makeMeasureSpec(Math.round(1920*scale),MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(Math.round(1080*scale),MeasureSpec.EXACTLY));}
        private void resize(ViewGroup parent,float ratio){for(int i=0;i<parent.getChildCount();i++){View v=parent.getChildAt(i);Geometry g=geometry.get(v);if(g==null){g=new Geometry(v);geometry.put(v,g);}g.apply(v,pixelScale);if(ratio!=1&&v.getBackground() instanceof android.graphics.drawable.GradientDrawable){android.graphics.drawable.GradientDrawable d=(android.graphics.drawable.GradientDrawable)v.getBackground();d.setCornerRadius(d.getCornerRadius()*ratio);}if(v instanceof ViewGroup&&!(v instanceof UpNextView))resize((ViewGroup)v,ratio);}}
        protected void onLayout(boolean changed,int l,int t,int r,int b){int w=overlay.getMeasuredWidth(),h=overlay.getMeasuredHeight(),x=(getWidth()-w)/2,y=(getHeight()-h)/2;overlay.layout(x,y,x+w,y+h);}
    }
    /** Weak keys let page controls disappear after removal; values contain no View references. */
    private static final class Geometry {
        int width,height,left,top,lastWidth,lastHeight,lastLeft,lastTop;final float font;
        Geometry(View v){FrameLayout.LayoutParams p=(FrameLayout.LayoutParams)v.getLayoutParams();width=lastWidth=p.width;height=lastHeight=p.height;left=lastLeft=p.leftMargin;top=lastTop=p.topMargin;font=v instanceof TextView?((TextView)v).getTextSize():0;}
        void apply(View v,float scale){FrameLayout.LayoutParams p=(FrameLayout.LayoutParams)v.getLayoutParams();if(p.width!=lastWidth)width=p.width;if(p.height!=lastHeight)height=p.height;if(p.leftMargin!=lastLeft)left=p.leftMargin;if(p.topMargin!=lastTop)top=p.topMargin;int w=width<0?width:Math.round(width*scale),h=height<0?height:Math.round(height*scale),x=Math.round(left*scale),y=Math.round(top*scale);if(p.width!=w||p.height!=h||p.leftMargin!=x||p.topMargin!=y){p.width=w;p.height=h;p.leftMargin=x;p.topMargin=y;v.setLayoutParams(p);}lastWidth=w;lastHeight=h;lastLeft=x;lastTop=y;if(font>0&&Math.abs(((TextView)v).getTextSize()-font*scale)>.1f)((TextView)v).setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,font*scale);}
    }

